const categoryLabels={Lua:"Lua environment",Lifecycle:"Lifecycle",script:"Script",game:"Game",Color:"Color",ServerSignal:"Server signals",ClientUIBaseControl:"Base UI control",ClientUICursorEventAreaControl:"Cursor event area",ClientUIPresetButtonControl:"Preset button",ClientUIAnimationControl:"Animation control",ClientUIGridScrollerControl:"Grid scroller",ClientUIImageControl:"Image control",CursorEventData:"Cursor data",Tween:"Tween",TweenSequence:"Tween sequence"};
const esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
const owners=[...new Set(API.functions.map(entry=>entry.owner))];let query="";const revealedReferences=new Set();
const search=document.querySelector("#search"),sections=document.querySelector("#function-sections"),dataSections=document.querySelector("#data-sections"),empty=document.querySelector("#empty");
document.querySelector("#game-version").textContent="Game "+API.gameVersion;document.querySelector("#docs-version").textContent="Docs v"+API.version;
document.querySelector("#category-nav").innerHTML=owners.map(owner=>'<a href="#category-'+esc(owner)+'"><span>'+esc(categoryLabels[owner]||owner)+'</span><b>'+API.functions.filter(entry=>entry.owner===owner).length+'</b></a>').join("");
document.querySelector("#data-nav").innerHTML='<a href="#properties"><span>Properties &amp; types</span><b>'+API.properties.length+'</b></a><a href="#enums"><span>Enums</span><b>'+API.enums.length+'</b></a>';
document.querySelector("#stats").innerHTML='<div><strong>'+API.functions.length+'</strong><span>functions</span></div><div><strong>'+owners.length+'</strong><span>categories</span></div><div><strong>'+API.enums.reduce((sum,item)=>sum+item.values.length,0)+'</strong><span>enum values</span></div>';
function details(entry){if(!entry.params.length&&!entry.returns.length)return"";return'<div class="signature-details">'+entry.params.map(param=>'<div class="detail-row"><span class="detail-kind">PARAM</span><code>'+esc(param.name)+'</code><code class="type">'+esc(param.type)+'</code><span>'+inlineDoc(param.description)+'</span></div>').join("")+entry.returns.map((item,index)=>'<div class="detail-row"><span class="detail-kind return">RETURN</span><code>'+esc(item.name||("value "+(index+1)))+'</code><code class="type">'+esc(item.type)+'</code><span>'+inlineDoc(item.description)+'</span></div>').join("")+'</div>'}
// Render only the documentation's small Markdown subset; never accept raw HTML.
function referenceId(target){
  const name=target.replace(/^EnumItem\./,'Enum.');
  const enumeration=API.enums.find(item=>name===item.name||name.startsWith(item.name+'.'));
  if(enumeration)return 'enum-'+enumeration.name;
  const method=API.functions.find(item=>target===item.owner+'.'+item.name||target===item.owner+item.separator+item.name||target===item.name);
  if(method)return method.owner+'-'+method.name;
  if(API.types.some(item=>item.name===target))return 'type-'+target;
  return null;
}
function referenceLink(label,target){
  const id=referenceId(target);
  return id?'<a class="api-reference" data-api-reference href="#'+esc(id)+'"><code>'+label+'</code></a>':'<code>'+label+'</code>';
}
function inlineDoc(value){
  return String(value).split(/(`[^`]+`)/g).map(part=>part.startsWith('`')?'<code>'+esc(part.slice(1,-1))+'</code>':esc(part).replace(/\[([^\]]+)\]\\?\(lua:\/\/([^)]+)\)/g,(_,label,target)=>referenceLink(label,target)).replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>')).join('');
}
function docBlocks(value){
  const lines=String(value).split('\n');let html='',paragraph=[],list='',code=null;
  const flush=()=>{if(paragraph.length){html+='<p>'+inlineDoc(paragraph.join(' '))+'</p>';paragraph=[];}if(list){html+='</'+list+'>';list='';}};
  for(const raw of lines){
    const line=raw.trim();
    if(line.startsWith('```')){flush();if(code!==null){html+='<pre><code>'+esc(code.join('\n'))+'</code></pre>';code=null;}else code=[];continue;}
    if(code!==null){code.push(raw);continue;}
    if(!line){flush();continue;}
    const heading=line.match(/^#{1,6}\s+(.+)/),item=line.match(/^(?:(\d+)\.\s+|[-*]\s+)(.+)/);
    if(heading){flush();html+='<h4>'+inlineDoc(heading[1])+'</h4>';continue;}
    if(item){const tag=item[1]?'ol':'ul';if(paragraph.length||list!==tag){flush();html+='<'+tag+'>';list=tag;}html+='<li>'+inlineDoc(item[2])+'</li>';continue;}
    if(list)flush();paragraph.push(line);
  }
  flush();if(code!==null)html+='<pre><code>'+esc(code.join('\n'))+'</code></pre>';return html;
}
const conciseDescriptions={
  'script.RegisterServerSignalHandler':'Registers a handler for a named Client Scripted Signal.\n\n- Only the first handler registered for each signal on a script takes effect.\n- Receives only signals sent by the **Send Client Scripted Signal** server node, with a minimum latency of approximately **100 ms**.\n- Read callback parameters by sequence index, in Server Signal Explorer order.',
  'game.FindClientUIRoot':'Finds a root-level ContainerControl by name; returns `nil` if none matches.\n\n- Duplicate names: returns the first control in runtime instantiation order.\n- Roots instantiate in descending order from the Interface Layout list.\n- When **Activate UI Control Group in Control Group Library** activates a Server Control Template containing a Client Container Control, the new root is appended to the hierarchy regardless of its template layer.',
  'TweenSequence.Append':'Appends a Tween to the end of the sequence and returns the current sequence.\n\n- The sequence must be in the **Initial** state.\n- Added Tweens become **Locked**. They must be **Initial** when added to animate or invoke callbacks.'
};
function description(entry){
  let text=conciseDescriptions[entry.owner+'.'+entry.name]||entry.description;
  if(entry.owner==='Lifecycle')text=text.replaceAll('the Client Control that the script is attached to','the attached Client Control').replaceAll('when a Client Control with the script attached is instantiated','when the attached Client Control is instantiated').replaceAll('Updates must be enabled for the script for this lifecycle function to be called.','Requires script updates to be enabled.');
  const order=text.indexOf('### Stage Start Lifecycle Function Call Order');
  const body=order<0?docBlocks(text):docBlocks(text.slice(0,order))+'<details class="doc-disclosure"'+(query.trim()?' open':'')+'><summary>Lifecycle call order</summary>'+docBlocks(text.slice(order).replace(/^### Stage Start Lifecycle Function Call Order\s*/,''))+'</details>';
  return '<div class="method-description">'+body+'</div>';
}
function card(entry){return'<article class="function-card" id="'+esc(entry.owner)+'-'+esc(entry.name)+'"><div class="function-head"><code>'+esc(entry.signature)+'</code><div class="function-actions"><button type="button" class="copy-button" data-copy="'+esc(entry.signature)+'" aria-label="Copy signature">Copy</button></div></div>'+description(entry)+(entry.note?'<div class="method-note"><strong>Note</strong> '+inlineDoc(entry.note)+'</div>':'')+details(entry)+'</article>'}
const queryMatches=(normalized,...values)=>values.flat(Infinity).filter(value=>value!==null&&value!==undefined).join(" ").toLowerCase().includes(normalized);
// Rank names without narrowing the full-text results: exact, prefix, substring, then references.
function nameScore(normalized,...names){
  if(!normalized)return 0;
  return Math.max(0,...names.filter(Boolean).map(value=>{
    const name=value.toLowerCase();
    return name===normalized?4:name.startsWith(normalized)?3:name.includes(normalized)?2:0;
  }));
}
function matchingFunctions(normalized){
  return API.functions.filter(entry=>!normalized||queryMatches(normalized,entry.owner,entry.name,entry.signature,entry.description,entry.note,entry.params.map(item=>[item.name,item.type,item.description]),entry.returns.map(item=>[item.name,item.type,item.description])))
    .sort((a,b)=>nameScore(normalized,b.name,b.owner+b.separator+b.name)-nameScore(normalized,a.name,a.owner+a.separator+a.name));
}
function groupEnum(name,values){
  const groups=new Map();
  for(const value of values){
    let label='';
    if(/KeyEventType|KeyCode/.test(name)){
      const device=name.endsWith('KeyEventType')?(value.startsWith('Keyboard')?'Keyboard · ':'Controller · '):'';
      const number=value.match(/CraftspersonKey(\d+)/)?.[1];
      label=device+(number?'Craftsperson '+(Math.floor((Number(number)-1)/10)*10+1)+'–'+Math.min(Math.floor((Number(number)-1)/10)*10+10,name.includes('Controller')||value.startsWith('Controller')?14:43):/CharacterSkill|NormalAttack/.test(value)?'Combat':/Move|Jump|Sprint|Walk|Run/.test(value)?'Movement':/Menu|Shortcut/.test(value)?'Menus':value==='None'?'Unassigned':'Interaction');
    }else if(name==='Enum.EaseType')label=value==='Linear'?'Linear':value.replace(/^(InOut|In|Out)/,'');
    else if(name==='Enum.ParamType')label=/List$/.test(value)?'Lists':'Single values';
    else if(name==='Enum.CursorEventType')label=/Drag/.test(value)?'Dragging':/Enter|Exit/.test(value)?'Hover':'Click & press';
    else if(name==='Enum.ControllerNavigationEventType')label=/LeftStick/.test(value)?'Left stick':/RightStick/.test(value)?'Right stick':'Selection & focus';
    else if(name==='Enum.LanguageType')label=value==='LanguageNone'?'Unspecified':'Languages';
    if(!groups.has(label))groups.set(label,[]);groups.get(label).push(value);
  }
  if(/KeyEventType|KeyCode|EaseType/.test(name))for(const members of groups.values())members.sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
  return [...groups];
}
function renderData(normalized){
  const hasQuery=Boolean(normalized);
  const typeResults=API.types.map(type=>{
    const owned=API.properties.filter(item=>item.owner===type.name);
    const typeMatch=!hasQuery||queryMatches(normalized,type.name,type.parent,type.description);
    const properties=hasQuery&&!typeMatch?owned.filter(item=>queryMatches(normalized,item.owner,item.name,item.type,item.description)):owned;
    if(hasQuery&&!typeMatch&&!properties.length)return null;
    if(!hasQuery&&!owned.length)return null;
    return{type,properties};
  }).filter(Boolean);
  const enumResults=API.enums.map(item=>{
    const enumMatch=!hasQuery||revealedReferences.has("enum-"+item.name)||queryMatches(normalized,item.name,item.description);
    const values=hasQuery&&!enumMatch?item.values.filter(value=>queryMatches(normalized,value)):item.values;
    return hasQuery&&!enumMatch&&!values.length?null:{item,values};
  }).filter(Boolean);
  const properties=typeResults.map(({type,properties:items})=>'<article class="property-card" id="type-'+esc(type.name)+'"><div class="property-title"><code>'+esc(type.name)+'</code>'+(type.parent?'<span>extends '+esc(type.parent)+'</span>':'')+'</div>'+(type.description?'<p class="type-description">'+inlineDoc(type.description)+'</p>':'')+items.map(item=>'<div class="property-row"><code>'+esc(item.name)+'</code><code>'+esc(item.type)+'</code><span>'+inlineDoc(item.description)+'</span></div>').join("")+'</article>').join("");
  const enums=enumResults.map(({item,values})=>'<article class="enum-card" id="enum-'+esc(item.name)+'"><header class="enum-heading"><code>'+esc(item.name)+'</code><span>'+values.length+(values.length!==item.values.length?' of '+item.values.length:'')+' values</span></header><div class="enum-groups">'+groupEnum(item.name,values).map(([label,members])=>'<section class="enum-group">'+(label?'<h3>'+esc(label)+'</h3>':'')+'<div class="enum-values">'+members.map(value=>'<code>'+esc(value)+'</code>').join('')+'</div></section>').join('')+'</div></article>').join('');
  const propertySection=typeResults.length?'<section class="api-section" id="properties"><div class="section-heading"><div><span class="section-number">P</span><h2>Properties &amp; types</h2></div><span>'+typeResults.length+' '+(typeResults.length===1?'type':'types')+'</span></div><div class="property-grid">'+properties+'</div></section>':'';
  const enumSection=enumResults.length?'<section class="api-section" id="enums"><div class="section-heading"><div><span class="section-number">E</span><h2>Enums</h2></div><span>'+enumResults.length+' '+(enumResults.length===1?'group':'groups')+'</span></div><div class="enum-list">'+enums+'</div></section>':'';
  dataSections.innerHTML=propertySection+enumSection;
  return typeResults.length+enumResults.length;
}
function render(){
  const normalized=query.trim().toLowerCase();let functionCount=0;
  if(normalized){
    const entries=matchingFunctions(normalized);functionCount=entries.length;
    sections.innerHTML=entries.length?'<section class="api-section"><div class="section-heading"><div><h2>Matching functions</h2></div><span>'+entries.length+' results · name matches first</span></div><div class="function-list">'+entries.map(card).join('')+'</div></section>':'';
  }else{
  sections.innerHTML=owners.map((owner,index)=>{const entries=API.functions.filter(entry=>entry.owner===owner&&(!normalized||queryMatches(normalized,entry.owner,entry.name,entry.signature,entry.description,entry.note,entry.params.map(item=>[item.name,item.type,item.description]),entry.returns.map(item=>[item.name,item.type,item.description]))));if(!entries.length)return"";functionCount+=entries.length;return'<section class="api-section" id="category-'+esc(owner)+'"><div class="section-heading"><div><span class="section-number">'+String(index+1).padStart(2,"0")+'</span><h2>'+esc(categoryLabels[owner]||owner)+'</h2></div><span>'+entries.length+' '+(entries.length===1?'function':'functions')+'</span></div><div class="function-list">'+entries.map(card).join("")+'</div></section>'}).join("");
  }
  const showData=true;
  const dataCount=showData?renderData(normalized):0;
  dataSections.classList.toggle("hidden",!showData||dataCount===0);
  empty.classList.toggle("hidden",functionCount+dataCount>0);
  empty.textContent=normalized?'No API entries match “'+query+'”.':'No API entries found.';
}
search.addEventListener("input",event=>{query=event.target.value;revealedReferences.clear();render()});document.addEventListener("keydown",event=>{if(event.key==="/"&&document.activeElement!==search){event.preventDefault();search.focus()}});
document.addEventListener("click",async event=>{const button=event.target.closest(".copy-button");if(!button)return;const text=button.dataset.copy;try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement("textarea");area.value=text;document.body.appendChild(area);area.select();document.execCommand("copy");area.remove()}button.textContent="Copied";setTimeout(()=>button.textContent="Copy",1200)});
let jumpFrame=0;
function fastJump(target,hash){
  cancelAnimationFrame(jumpFrame);
  if(hash)history.pushState(null,"",hash);
  const margin=parseFloat(getComputedStyle(target).scrollMarginTop)||0;
  const start=window.scrollY;
  const destination=Math.max(0,target.getBoundingClientRect().top+start-margin);
  const distance=destination-start;
  if(matchMedia("(prefers-reduced-motion: reduce)").matches||Math.abs(distance)<2){window.scrollTo(0,destination);return}
  const started=performance.now(),duration=120;
  const step=now=>{const progress=Math.min(1,(now-started)/duration);const eased=1-Math.pow(1-progress,3);window.scrollTo(0,start+distance*eased);if(progress<1)jumpFrame=requestAnimationFrame(step)};
  jumpFrame=requestAnimationFrame(step);
}
document.addEventListener("click",event=>{const link=event.target.closest('a[href^="#"]');if(!link)return;const hash=link.getAttribute("href");if(!hash||hash==="#")return;if(link.hasAttribute("data-api-reference")&&query.trim()){revealedReferences.add(decodeURIComponent(hash.slice(1)));render();}const target=document.getElementById(decodeURIComponent(hash.slice(1)));if(!target)return;event.preventDefault();fastJump(target,hash)});
const theme=document.querySelector("#theme-toggle");const saved=localStorage.getItem("mililua-theme");const dark=saved?saved==="dark":matchMedia("(prefers-color-scheme:dark)").matches;document.documentElement.dataset.theme=dark?"dark":"light";function themeLabel(){const isDark=document.documentElement.dataset.theme==="dark";theme.textContent=isDark?"☀":"☾";theme.setAttribute("aria-label","Switch to "+(isDark?"light":"dark")+" mode")}themeLabel();theme.addEventListener("click",()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==="dark"?"light":"dark";localStorage.setItem("mililua-theme",document.documentElement.dataset.theme);themeLabel()});
